package oepul.o6_1c

# Definition und Förderverpflichtungen der Kategorie "Agroforststreifen".

afs_params := params.agroforest

# O6_1C-APP-005: Bei Teilnahme an der Kategorie müssen alle beantragten
# Agroforststreifen nach den Förderverpflichtungen bewirtschaftet werden.
afs_parcels contains p if {
	some p in parcels
	object.get(p, ["o6_1c", "category"], null) == "agroforest"
}

afs_parcels contains p if {
	"agroforest" in applied_categories
	some p in parcels
	object.get(p, "field_use_type", null) == params.application.agroforest_field_use_type
}

afs(p) := object.get(p, ["o6_1c", "agroforest"], {})

trees_per_100_m(p) := (afs(p).tree_count * 100) / afs(p).length_m if afs(p).length_m > 0

negative_list_names := {lower(row.scientific_name) | some row in data.o6_1c.agroforest_negative_list.rows; row.taxon_rank == "species"}

negative_list_genera := {lower(row.scientific_name) | some row in data.o6_1c.agroforest_negative_list.rows; row.taxon_rank == "genus"}

on_negative_list(species) if lower(species) in negative_list_names

on_negative_list(species) if {
	some genus in negative_list_genera
	startswith(lower(species), genus)
}

afs_woody_species(p) := {s | some s in object.get(afs(p), "woody_species", [])}

# Definitionsmerkmale (O6_1C-AFS-DEF-001 bis -010).
afs_definition_violations contains violation("O6_1C-AFS-DEF-001", p, "Agroforststreifen muss direkt an Ackerflächen angrenzen") if {
	some p in afs_parcels
	afs(p).directly_adjacent_to_arable == false
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-002", p, "Agroforststreifen muss ab dem Jahr 2020 neu angelegt worden sein") if {
	some p in afs_parcels
	afs(p).establishment_year < afs_params.earliest_establishment_year
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-003", p, "Durchschnittliche Breite muss mindestens 2 m und höchstens 10 m betragen") if {
	some p in afs_parcels
	w := afs(p).average_width_m
	not width_in_range(w)
}

width_in_range(w) if {
	w >= afs_params.min_average_width_m
	w <= afs_params.max_average_width_m
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-004", p, "Dichte muss mindestens 10 bis höchstens 25 Bäume pro 100 Laufmeter betragen") if {
	some p in afs_parcels
	d := trees_per_100_m(p)
	not density_in_range(d)
}

density_in_range(d) if {
	d >= afs_params.min_trees_per_100_m
	d <= afs_params.max_trees_per_100_m
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-005", p, "Maximaler Baumabstand von 15 m überschritten") if {
	some p in afs_parcels
	afs(p).max_tree_spacing_m > afs_params.max_tree_spacing_m
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-006", p, "Agroforststreifen darf keiner Spezialkultur gemäß § 25 Abs. 4 GSP-AV entsprechen") if {
	some p in afs_parcels
	afs(p).is_special_crop_gsp_av_25_4 == true
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-008", p, sprintf("Gehölz der Negativliste vorhanden (%s); darf nicht gepflanzt werden bzw. ist bei natürlichem Anflug zu entfernen", [s])) if {
	some p in afs_parcels
	some s in afs_woody_species(p)
	on_negative_list(s)
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-009", p, "Agroforststreifen darf entlang der Längsseite nicht an Wald oder ein flächiges Landschaftselement angrenzen") if {
	some p in afs_parcels
	afs(p).long_side_adjacent_to_forest_or_areal_landscape_element == true
}

afs_definition_violations contains violation("O6_1C-AFS-DEF-010", p, "Agroforststreifen muss sich auf einer Referenzfläche befinden oder unmittelbar an eine solche angrenzen") if {
	some p in afs_parcels
	afs(p).on_or_adjacent_to_reference_area == false
}

# O6_1C-AFS-DEF-007: Pflanzung von Sträuchern zwischen den Bäumen zulässig
# (keine Verletzung); als Information ausgegeben.
afs_shrubs_permitted contains parcel_id(p) if {
	some p in afs_parcels
	afs(p).shrubs_between_trees == true
}

afs_meets_definition(p) if {
	p in afs_parcels
	count({v | some v in afs_definition_violations; v.parcel_id == parcel_id(p)}) == 0
}

# O6_1C-AFS-001: Neuanlage bis spätestens 15. Mai des Antragsjahres.
afs_commitment_violations contains violation("O6_1C-AFS-001", p, "Neuanlage des Agroforststreifens bis spätestens 15. Mai des Antragsjahres") if {
	some p in afs_parcels
	afs(p).establishment == "new_planting"
	afs(p).planting_date > date_of(year, afs_params.latest_planting_mmdd)
}

# O6_1C-AFS-002: Entnahme von Gehölzen nur, wenn Mindestkriterien weiter
# eingehalten werden oder Nachpflanzung bis 15. Mai.
timely_replanting(p) if {
	rd := object.get(afs(p), "replanting_date", null)
	rd != null
	rd <= date_of(year, afs_params.latest_replanting_mmdd)
}

afs_commitment_violations contains violation("O6_1C-AFS-002", p, "Gehölzentnahme ohne Einhaltung der Mindestkriterien und ohne Nachpflanzung bis 15. Mai") if {
	some p in afs_parcels
	afs(p).woody_plants_removed == true
	not afs_meets_definition(p)
	not timely_replanting(p)
}

# O6_1C-AFS-003: Pflege – Pflanzpfahl, Verbissschutz, bedarfsgerechte Pflegeschnitte.
afs_commitment_violations contains violation("O6_1C-AFS-003", p, sprintf("Unbedingt erforderliche Pflegemaßnahme fehlt: %s", [k])) if {
	some p in afs_parcels
	some k in ["staking", "browsing_protection", "pruning_as_needed"]
	object.get(afs(p), ["care", k], true) == false
}

# O6_1C-AFS-004: Krautiger Bereich dauerhaft begrünt.
afs_commitment_violations contains violation("O6_1C-AFS-004", p, "Der krautige Bereich ist dauerhaft zu begrünen") if {
	some p in afs_parcels
	afs(p).herbaceous_area_permanently_green == false
}

# O6_1C-AFS-005: Keine Nutzung des krautigen Bereichs (Mahd oder Weide);
# Pflegemahd ohne Abtransport oder Häckseln erlaubt.
afs_commitment_violations contains violation("O6_1C-AFS-005", p, "Nutzung des krautigen Bereichs (Mahd mit Abtransport oder Weide) ist nicht zulässig") if {
	some p in afs_parcels
	afs(p).herbaceous_area_use in {"mowing_with_removal", "grazing"}
}

# O6_1C-AFS-006: Dünge- und Pflanzenschutzmittelverbot auf der gesamten Fläche;
# nur Bio-zugelassener Verbissschutz zulässig.
afs_commitment_violations contains violation("O6_1C-AFS-006", p, "Einsatz von Düngemitteln auf dem Agroforststreifen verboten") if {
	some p in afs_parcels
	afs(p).fertilizer_used == true
}

afs_commitment_violations contains violation("O6_1C-AFS-006", p, "Einsatz von Pflanzenschutzmitteln auf dem Agroforststreifen verboten") if {
	some p in afs_parcels
	afs(p).psm_used == true
}

afs_commitment_violations contains violation("O6_1C-AFS-006", p, "Nur gemäß VO (EU) 2018/848 zugelassener Verbissschutz zulässig") if {
	some p in afs_parcels
	afs(p).browsing_protection_agent_used == true
	not afs(p).browsing_protection_agent_bio_approved == true
}

# O6_1C-APP-004: Beantragung als Schlagnutzungsart "LSE Agroforststreifen".
afs_commitment_violations contains violation("O6_1C-APP-004", p, "Agroforststreifen sind mit der Schlagnutzungsart LSE Agroforststreifen zu beantragen") if {
	some p in afs_parcels
	object.get(p, "field_use_type", null) != params.application.agroforest_field_use_type
}

# O6_1C-AFS-007: Dem Feldstück zugeordnete Agroforststreifen werden bei UBB/BIO
# für die 0,15 ha Biodiversitätsflächen auf Ackerfeldstücken > 5 ha angerechnet
# (nicht jedoch für die 7-%-Grenze).
afs_area_by_field_piece[fp] := a if {
	some fp in ({object.get(afs(p), "assigned_field_piece_id", null) | some p in afs_parcels} - {null})
	a := sum([object.get(q, "area_ha", 0) |
		some q in afs_parcels
		object.get(afs(q), "assigned_field_piece_id", null) == fp
		afs_meets_definition(q)
	])
}

ubb_bio_creditable_afs_area_by_field_piece[fp] := a if {
	some fp, a in afs_area_by_field_piece
	some piece in object.get(input, ["land", "field_pieces"], [])
	piece.field_piece_id == fp
	piece.arable_area_ha > params.general.ubb_bio_field_piece_threshold_ha
}

afs_counts_towards_ubb_bio_seven_percent := false

# O6_1C-AFS-008: Umwandlung von Flächen mehrjähriger Maßnahmen in LSE
# Agroforststreifen ist ein zulässiger Flächenabgang (keine Rückzahlung).
conversion_permitted(from_use, to_use) if {
	some row in data.o6_1c.permitted_land_use_conversions.rows
	row.to == to_use
	some f in row.from
	f in {"*", from_use}
}

package oepul.o6_1c

# Beantragung, Vertragszeitraum, Verlängerung und Abmeldung.

first_contract_year := application.first_contract_year

# O6_1C-APP-001: Beantragung vor Vertragsbeginn bis 31.12. des Vorjahres.
application_deadline := date_of(first_contract_year - 1, params.application.measure_application_deadline_mmdd)

application_violations contains farm_violation("O6_1C-APP-001", sprintf("Maßnahmenantrag muss bis %s eingelangt sein", [application_deadline])) if {
	application.application_date > application_deadline
}

application_violations contains farm_violation("O6_1C-APP-001", "Kategorie muss im Maßnahmenantrag des Mehrfachantrages beantragt werden") if {
	count(applied_categories) == 0
}

# O6_1C-APP-002: Letzter Einstieg mit Förderjahr 2027.
application_violations contains farm_violation("O6_1C-APP-002", "Letzter Einstieg ist mit dem Förderjahr 2027 möglich (Beantragung bis 31.12.2026)") if {
	first_contract_year > params.application.last_entry_year
}

# O6_1C-CONTRACT-001: Vertrags- und Verpflichtungszeitraum = Kalenderjahr.
commitment_period := {
	"start": date_of(year, "01-01"),
	"end": date_of(year, "12-31"),
}

# O6_1C-CONTRACT-002: automatische Verlängerung, wenn nicht abgemeldet.
deregistration_date := object.get(application, "deregistration_date", null)

contract_extended_into_year if {
	first_contract_year < year
	not contract_ended_before_year
}

contract_ended_before_year if {
	deregistration_date != null
	deregistration_date < date_of(year, "01-01")
}

# O6_1C-APP-007: Abmeldung zwischen 1.1. und 31.12. -> Maßnahme im
# betroffenen Förderjahr nicht mehr gültig.
deregistered_in_year if {
	deregistration_date != null
	deregistration_date >= commitment_period.start
	deregistration_date <= commitment_period.end
}

# O6_1C-APP-010: Wiedereinstieg nach Ausstieg, Ausschluss oder einjähriger
# Nichtabgabe des Mehrfachantrages nur mit neuerlichem Maßnahmenantrag.
application_violations contains farm_violation("O6_1C-APP-010", "Wiedereinstieg nur mit neuerlichem Maßnahmenantrag möglich") if {
	application.reentry_after_exit_or_exclusion == true
	not application.new_measure_application_submitted == true
}

# O6_1C-APP-011: Weiterführung durch Abgabe des Mehrfachantrages mit
# förderrelevanten Flächen.
continuation_requested if {
	contract_extended_into_year
	application.multiple_application_submitted == true
	count(npa_parcels | afs_parcels) > 0
}

application_violations contains farm_violation("O6_1C-APP-011", "Weiterführung erfordert die Abgabe des Mehrfachantrages mit förderrelevanten Flächen") if {
	contract_extended_into_year
	not continuation_requested
}

# O6_1C-APP-012: Maßnahmenübernahme bis 15.04. (2023 und 2028: 17.04.),
# Ausweitung auf andere Flächen höchstens 50 %.
takeover_deadline(y) := date_of(y, params.application.takeover_deadline_mmdd_2023_2028) if y in {2023, 2028}

takeover_deadline(y) := date_of(y, params.application.takeover_deadline_mmdd) if not y in {2023, 2028}

takeover := object.get(application, "takeover", null)

application_violations contains farm_violation("O6_1C-APP-012", sprintf("Maßnahmenübernahme nur bis %s möglich", [takeover_deadline(year)])) if {
	takeover != null
	takeover.date > takeover_deadline(year)
}

application_violations contains farm_violation("O6_1C-APP-012", "Maßnahmenübernahme darf nicht zu einer Ausweitung auf andere Flächen um mehr als 50 % führen") if {
	takeover != null
	takeover.additional_area_ha > params.application.takeover_max_extension_share * takeover.taken_over_area_ha
}

# O6_1C-APP-006: Feldstücksliste (Lage, Ausmaß, Schlagnutzung, Codes) bis
# spätestens 15. April des Antragsjahres.
field_list_deadline := date_of(year, params.application.field_list_deadline_mmdd)

application_violations contains farm_violation("O6_1C-APP-006", sprintf("Feldstücksliste des Mehrfachantrages ist bis %s einzureichen", [field_list_deadline])) if {
	application.field_list_submission_date > field_list_deadline
}

package oepul.o6_1c

# Zugangs- und Fördervoraussetzungen auf Betriebsebene.

applicant := object.get(input, ["farm", "applicant"], {})

lists := data.o6_1c

# O6_1C-SCOPE-002: Maßnahme wird ab dem Antragsjahr 2025 angeboten.
measure_offered if year >= params.application.first_offered_year

access_violations contains farm_violation("O6_1C-SCOPE-002", "Die Maßnahme wird erst ab dem Antragsjahr 2025 angeboten") if {
	not measure_offered
}

# O6_1C-ELIG-001: Teilnahme an der Kategorie NPA schließt UBB und BIO
# (ausgenommen BIO-Teilbetrieb Wein, Obst und Hopfen) am Betrieb aus.
npa_farm_level_conflicts contains row.measure_id if {
	"npa" in applied_categories
	some row in lists.npa_farm_level_exclusions.rows
	row.measure_id in participating_measures
	not npa_exclusion_exception_applies(row)
}

npa_exclusion_exception_applies(row) if {
	row.exception == "bio_partial_farm_wine_fruit_hops"
	object.get(oepul, "bio_participation_type", null) == "partial_wine_fruit_hops"
}

access_violations contains farm_violation("O6_1C-ELIG-001", sprintf("Kategorie Nichtproduktive Ackerflächen nicht gleichzeitig mit %s möglich", [m])) if {
	some m in npa_farm_level_conflicts
}

# O6_1C-ELIG-002: Gebietskörperschaften und Einrichtungen mit bestimmendem
# Einfluss (> 25 %) sind ausgeschlossen, ausgenommen in Ausnahme-Maßnahmen.
public_body_influence if applicant.type == "public_body"

public_body_influence if {
	object.get(applicant, "public_body_share_percent", 0) > params.general.max_public_body_share_percent
}

public_body_exception_applies if {
	some row in lists.public_body_exception_measures.rows
	row.measure_id == measure_id
	year_within(year, row.from_year, row.to_year)
}

year_within(y, from, to) if {
	from_ok(y, from)
	to_ok(y, to)
}

from_ok(_, null)

from_ok(y, from) if {
	from != null
	y >= from
}

to_ok(_, null)

to_ok(y, to) if {
	to != null
	y <= to
}

access_violations contains farm_violation("O6_1C-ELIG-002", "Gebietskörperschaft bzw. Einrichtung mit bestimmendem Einfluss einer Gebietskörperschaft ist im betroffenen Jahr nicht förderwerbend") if {
	public_body_influence
	not public_body_exception_applies
}

# O6_1C-ELIG-003: aktiver Landwirt und landwirtschaftliche Tätigkeit.
access_violations contains farm_violation("O6_1C-ELIG-003", "Förderwerbende Person muss aktiver Landwirt sein und eine landwirtschaftliche Tätigkeit ausüben") if {
	applicant.is_active_farmer == false
}

access_violations contains farm_violation("O6_1C-ELIG-003", "Förderwerbende Person muss aktiver Landwirt sein und eine landwirtschaftliche Tätigkeit ausüben") if {
	applicant.carries_out_agricultural_activity == false
}

# O6_1C-ELIG-004: Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr.
first_oepul_year if object.get(oepul, "first_participation_year", null) == year

minimum_farm_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= params.general.minimum_farm_size_protected_cultivation_ha
}

minimum_farm_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= params.general.minimum_farm_size_agricultural_area_ha
}

access_violations contains farm_violation("O6_1C-ELIG-004", "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (0,50 ha geschützter Anbau oder 1,50 ha landwirtschaftliche Fläche) nicht erreicht") if {
	first_oepul_year
	not minimum_farm_size_met
}

# O6_1C-ELIG-006: Bei einjährigen Maßnahmen kommt bei Nichterfüllung von
# Förder- bzw. Zugangsvoraussetzungen kein Vertrag zustande.
is_one_year_measure if {
	some row in lists.one_year_measures.rows
	row.measure_id == measure_id
}

contract_valid if {
	is_one_year_measure
	count(access_violations) == 0
	count(application_violations) == 0
	not deregistered_in_year
	not contract_ended_before_year
}

package oepul.o6_1c

# Allgemeine Förderfähigkeit von Flächen (Allgemeine Teilnahmebedingungen,
# SRL ÖPUL 2023 Punkt 1.6/1.7, GSP-AV §§ 27-31).

measure_parcels := npa_parcels | afs_parcels

# O6_1C-GEN-001: Nationalparks.
national_park_row(name) := row if {
	some row in data.o6_1c.national_parks.rows
	row.name == name
}

national_park_excluded(p) if {
	np := object.get(p, "national_park", {})
	np.in_national_park == true
	np.relevant_management_restrictions == true
}

national_park_excluded(p) if {
	np := object.get(p, "national_park", {})
	np.in_national_park == true
	only_for := national_park_row(np.name).area_premiums_only_for
	only_for != null
	not measure_id in {m | some m in only_for}
}

national_park_excluded(p) if {
	np := object.get(p, "national_park", {})
	np.in_national_park == true
	measure_id in {m | some m in national_park_row(np.name).not_eligible_measures}
}

parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-001"} if {
	some p in measure_parcels
	national_park_excluded(p)
}

# O6_1C-GEN-002: Code OP – im jeweiligen Förderjahr keine ÖPUL-Prämie.
op_coded(p) if "OP" in parcel_codes(p)

parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-002"} if {
	some p in measure_parcels
	op_coded(p)
}

# O6_1C-GEN-003: Versuchsflächen (Code VF) – keine Prämie im laufenden Jahr.
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-003"} if {
	some p in measure_parcels
	"VF" in parcel_codes(p)
}

# O6_1C-GEN-004: Unterjährige Weitergabe nur bei Weiterführung durch den
# übernehmenden Betrieb; sonst Code OP und keine Prämie.
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-004"} if {
	some p in measure_parcels
	object.get(p, ["transfer", "transferred_during_year"], false) == true
	not object.get(p, ["transfer", "successor_continues_commitment"], false) == true
}

general_violations contains violation("O6_1C-GEN-004", p, "Unterjährig weitergegebene Fläche ohne Weiterführung durch den Nachfolgebetrieb ist mit Code OP zu versehen") if {
	some p in measure_parcels
	object.get(p, ["transfer", "transferred_during_year"], false) == true
	not object.get(p, ["transfer", "successor_continues_commitment"], false) == true
	not op_coded(p)
}

# O6_1C-GEN-005: Leistungsüberschneidung mit anderem Titel der öffentlichen
# Hand bzw. gesetzlich/behördlich vorgeschriebene Auflagen -> nicht förderbar (Code OP).
overlap(p) if object.get(p, "public_funding_overlap", false) == true

overlap(p) if object.get(p, "statutory_requirement_overlap", false) == true

parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-005"} if {
	some p in measure_parcels
	overlap(p)
}

general_violations contains violation("O6_1C-GEN-005", p, "Bei Leistungsüberschneidung bzw. behördlich vorgeschriebenen Auflagen ist der Code OP zu vergeben") if {
	some p in measure_parcels
	overlap(p)
	not op_coded(p)
}

# O6_1C-GEN-006: Reines Fremdverschulden -> maßnahmenbezogener OP-Code,
# keine Prämie auf der betroffenen Schlagfläche.
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-006"} if {
	some p in measure_parcels
	object.get(p, "third_party_fault_noncompliance", false) == true
}

# O6_1C-GEN-007: Mindestgröße förderfähiger Flächen 50 m².
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-007"} if {
	some p in measure_parcels
	object.get(p, "area_ha", 0) * 10000 < params.general.minimum_eligible_area_m2
}

# O6_1C-ELIG-005: Geförderte Flächen müssen in Österreich liegen.
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-ELIG-005"} if {
	some p in measure_parcels
	object.get(p, "in_austria", true) == false
}

# O6_1C-GEN-008: Nicht förderfähige Flächenarten (Ausnahme Grünbrachen in o6_1c).
non_eligible_type(t) if {
	some row in data.o6_1c.non_eligible_area_types.rows
	row.type == t
	not measure_id in {m | some m in row.exception_measures}
}

parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-008"} if {
	some p in measure_parcels
	some t in object.get(p, "non_eligible_area_types", [])
	non_eligible_type(t)
}

# O6_1C-GEN-009: Nicht für die Maßnahme angegebene oder falsch identifizierte
# Flächen sind nicht förderfähig.
parcel_exclusions contains {"parcel_id": parcel_id(p), "rule_id": "O6_1C-GEN-009"} if {
	some p in measure_parcels
	object.get(p, "correctly_identified", true) == false
}

excluded_parcel_ids := {e.parcel_id | some e in parcel_exclusions}

eligible(p) if not parcel_id(p) in excluded_parcel_ids

# O6_1C-NPA-018: NPA und Agroforststreifen sind von den
# Mindestbewirtschaftungskriterien (Ernte, Gründecke) ausgenommen.
minimum_management_exempt if {
	some row in data.o6_1c.minimum_management_exempt_areas.rows
	measure_id in {m | some m in row.measures}
}

package oepul.o6_1c

# Förderverpflichtungen der Kategorie "Nichtproduktive Ackerflächen" (NPA).

npa_params := params.npa

npa_parcels contains p if {
	some p in parcels
	object.get(p, ["o6_1c", "category"], null) == "npa"
}

npa(p) := object.get(p, ["o6_1c", "npa"], {})

npa_establishment_types := {"new_sowing", "self_greening", "retained_existing"}

# O6_1C-NPA-001: Neuansaat (Selbstbegrünung zulässig) oder Belassen bestehender
# Grünbrachen bzw. dauerhaft begrünter Ackerflächen.
npa_violations contains violation("O6_1C-NPA-001", p, "Neuansaat/Selbstbegrünung oder Belassen einer bestehenden Grünbrache bzw. dauerhaft begrünten Ackerfläche erforderlich") if {
	some p in npa_parcels
	not npa(p).establishment in npa_establishment_types
}

# O6_1C-NPA-002: Neuansaat bis spätestens 15. Mai des Antragsjahres.
npa_violations contains violation("O6_1C-NPA-002", p, "Neuansaat muss bis spätestens 15. Mai des Antragsjahres erfolgen") if {
	some p in npa_parcels
	npa(p).establishment == "new_sowing"
	npa(p).sowing_date > date_of(year, npa_params.latest_new_sowing_mmdd)
}

# O6_1C-NPA-003 / O6_1C-NPA-004: Umbruch frühestens 15.09.; bei Anbau einer
# Winterung oder Zwischenfrucht bereits ab 01.08.
earliest_breaking_date(p) := date_of(year, npa_params.earliest_breaking_with_follow_crop_mmdd) if {
	object.get(npa(p), "follow_crop", "none") in {c | some c in npa_params.follow_crops_allowing_early_breaking}
}

earliest_breaking_date(p) := date_of(year, npa_params.earliest_breaking_mmdd) if {
	not object.get(npa(p), "follow_crop", "none") in {c | some c in npa_params.follow_crops_allowing_early_breaking}
}

npa_violations contains violation("O6_1C-NPA-003", p, sprintf("Umbruch erst ab %s zulässig", [earliest_breaking_date(p)])) if {
	some p in npa_parcels
	bd := object.get(npa(p), "breaking_date", null)
	bd != null
	bd < earliest_breaking_date(p)
}

# O6_1C-NPA-005: Kein Pflanzenschutzmittel (außer Bio-Wirkstoffe) und keine
# Düngung ab 01.01. des ersten Antragsjahres bis zum Umbruch.
npa_psm_violation(p) if {
	object.get(p, ["operations", "psm_used"], false) == true
	not npa(p).psm_only_bio_permitted_substances == true
}

npa_fertilized(p) if npa(p).fertilizer_applied == true

npa_fertilized(p) if object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0

npa_fertilized(p) if object.get(p, ["operations", "fertilizer", "organic_n_kg_per_ha"], 0) > 0

npa_violations contains violation("O6_1C-NPA-005", p, "Einsatz von Pflanzenschutzmitteln (ausgenommen gemäß VO (EU) 2018/848 zulässige Wirkstoffe) verboten") if {
	some p in npa_parcels
	npa_psm_violation(p)
}

npa_violations contains violation("O6_1C-NPA-005", p, "Jegliche Düngung ist bis zum Umbruch bzw. zur anderweitigen Deklaration verboten") if {
	some p in npa_parcels
	npa_fertilized(p)
}

# O6_1C-NPA-006: Beseitigung nur mechanisch (Häckseln oder Einarbeiten).
npa_violations contains violation("O6_1C-NPA-006", p, "Beseitigung nur mit mechanischen Methoden (Häckseln oder Einarbeiten) zulässig") if {
	some p in npa_parcels
	method := object.get(npa(p), "removal_method", "none")
	not method in {m | some m in npa_params.allowed_removal_methods}
}

# O6_1C-NPA-011 / O6_1C-NPA-012: Reinigungsschnitt nur im ersten Antragsjahr
# auf Flächen mit Neuansaat (oder Umbruch und Neueinsaat bestehender Grünbrachen).
cleaning_cut_permitted(p) if {
	object.get(npa(p), "first_application_year", null) == year
	npa(p).establishment in {"new_sowing", "self_greening"}
}

cleaning_cut_permitted(p) if {
	object.get(npa(p), "first_application_year", null) == year
	npa(p).existing_green_fallow_broken_and_resown == true
}

cut_events(p) := object.get(npa(p), "cutting_events", [])

# Schnitte, die zur Höchstanzahl und 50-%-Grenze zählen.
regular_cuts(p) := [e |
	some e in cut_events(p)
	counts_as_regular_cut(p, e)
]

counts_as_regular_cut(_, e) if e.type in {"care_mowing", "mulching"}

counts_as_regular_cut(p, e) if {
	e.type == "cleaning_cut"
	not cleaning_cut_permitted(p)
}

npa_violations contains violation("O6_1C-NPA-012", p, "Reinigungsschnitt nur im ersten Antragsjahr auf Flächen mit Neuansaat zulässig, nicht auf bestehenden Grünbrachen") if {
	some p in npa_parcels
	some e in cut_events(p)
	e.type == "cleaning_cut"
	not cleaning_cut_permitted(p)
}

# O6_1C-NPA-007: Pflegemahd oder Häckseln mindestens 1 x jedes zweite Jahr.
npa_violations contains violation("O6_1C-NPA-007", p, "Pflegemahd oder Häckseln mindestens einmal jedes zweite Jahr erforderlich") if {
	some p in npa_parcels
	count(regular_cuts(p)) == 0
	npa(p).cut_in_previous_year == false
	object.get(application, "commitment_year_completed", false) == true
}

# O6_1C-NPA-008: Mähen/Häckseln maximal 2 x pro Jahr.
npa_violations contains violation("O6_1C-NPA-008", p, "Mähen/Häckseln maximal zweimal pro Jahr erlaubt") if {
	some p in npa_parcels
	count(regular_cuts(p)) > npa_params.max_cuts_per_year
}

# O6_1C-NPA-009: Mähgut nicht verbringen/nutzen; keine Beweidung.
npa_violations contains violation("O6_1C-NPA-009", p, "Mähgut darf nicht von der Fläche verbracht und genutzt werden") if {
	some p in npa_parcels
	some e in cut_events(p)
	e.biomass_removed == true
}

npa_violations contains violation("O6_1C-NPA-009", p, "Beweidung nichtproduktiver Ackerflächen ist nicht erlaubt") if {
	some p in npa_parcels
	npa(p).grazed == true
}

# O6_1C-NPA-010: Auf 50 % der NPA-Fläche je Kalenderjahr Mähen/Häckseln
# frühestens am 1. August (Reinigungsschnitt zählt nicht).
restricted_cut_date := date_of(year, npa_params.earliest_restricted_cut_mmdd)

early_cut_parcels contains p if {
	some p in npa_parcels
	some e in regular_cuts(p)
	e.date < restricted_cut_date
}

npa_total_area_ha := sum_area(npa_parcels)

npa_early_cut_area_ha := sum_area(early_cut_parcels)

farm_npa_violations contains farm_violation("O6_1C-NPA-010", "Mähen/Häckseln vor dem 1. August auf mehr als 50 % der nichtproduktiven Ackerflächen") if {
	npa_early_cut_area_ha > npa_params.restricted_cut_share * npa_total_area_ha
}

# O6_1C-NPA-013: Nach Umbruch Nutzungsverbot bis einschließlich 31.12.
npa_violations contains violation("O6_1C-NPA-013", p, "Nach Umbruch gilt bis einschließlich 31. Dezember ein Nutzungsverbot") if {
	some p in npa_parcels
	object.get(npa(p), "breaking_date", null) != null
	npa(p).used_after_breaking == true
}

# O6_1C-NPA-015: NPA prämienmäßig mit keiner anderen Maßnahme auf der
# Einzelfläche kombinierbar (Anhang L, Zeile/Spalte 1C leer).
annex_l_cell(row, col) := cell if {
	some cell in data.o6_1c.annex_l_combination.cells
	cell.row == row
	cell.col == col
}

combinable_on_single_area(row, col) if annex_l_cell(row, col).combinable == true

measure_code(m) := upper(trim_prefix(m, "o6_"))

npa_violations contains violation("O6_1C-NPA-015", p, sprintf("Nichtproduktive Ackerfläche ist prämienmäßig nicht mit %s auf der Einzelfläche kombinierbar", [m])) if {
	some p in npa_parcels
	some m in object.get(p, "other_oepul_measures", [])
	not combinable_on_single_area("1C", measure_code(m))
}

npa_violations contains violation("O6_1C-NPA-015", p, "Nichtproduktive Ackerflächen können nicht auf andere Verpflichtungen der SRL ÖPUL 2023 angerechnet werden") if {
	some p in npa_parcels
	count(object.get(npa(p), "credited_to_other_obligations", [])) > 0
}

# O6_1C-APP-003: NPA in der Feldstücksliste als "Grünbrache" mit Code NPA.
npa_violations contains violation("O6_1C-APP-003", p, "Nichtproduktive Ackerflächen sind mit Schlagnutzungsart Grünbrache und Code NPA zu beantragen") if {
	some p in npa_parcels
	object.get(p, "field_use_type", null) != params.application.npa_field_use_type
}

npa_violations contains violation("O6_1C-APP-003", p, "Nichtproduktive Ackerflächen sind mit Schlagnutzungsart Grünbrache und Code NPA zu beantragen") if {
	some p in npa_parcels
	not params.application.npa_code in parcel_codes(p)
}

# O6_1C-NPA-016: GLÖZ-4-Pufferstreifen auf dem betroffenen Flächenteil nicht förderbar.
npa_gloez4_area_ha(p) := min_of(object.get(npa(p), "gloez4_buffer_area_ha", 0), object.get(p, "area_ha", 0))

# O6_1C-NPA-017: NPA von der Grünlandwerdung ausgenommen.
excluded_from_grassland_conversion contains parcel_id(p) if {
	some p in npa_parcels
}

# O6_1C-COMB-001: Auswertung einer Zelle aus Anhang L inkl. Legende (x/a) und
# Fußnoten 1) bis 4) als Einschränkung der Kombinierbarkeit.
annex_l_footnote_text(id) := fn.text if {
	some fn in data.o6_1c.annex_l_combination.footnotes
	fn.id == id
}

combination_assessment(row, col) := {
	"combinable": cell.combinable,
	"premium_deduction": cell.premium_deduction,
	"restriction": annex_l_footnote_text(cell.footnote),
} if {
	cell := annex_l_cell(row, col)
	cell.footnote != null
}

combination_assessment(row, col) := {
	"combinable": cell.combinable,
	"premium_deduction": cell.premium_deduction,
	"restriction": null,
} if {
	cell := annex_l_cell(row, col)
	cell.footnote == null
}

package oepul.o6_1c

# Kürzungen, Sanktionen, Flächenabweichungen und höhere Gewalt.

stages := data.o6_1c.sanction_stages

stage_row(stage) := row if {
	some row in stages.rows
	row.stage == stage
}

# O6_1C-SANC-001: Sanktionsstufen; ab 2027 Einbehalt 1 % statt Verwarnung.
stage_percent(stage, y) := stage_row(stage).reduction_percent_from_2027 if y >= stages.warning_replaced_from_year

stage_percent(stage, y) := stage_row(stage).reduction_percent if y < stages.warning_replaced_from_year

# O6_1C-SANC-003: Mehrmaliger Verstoß bei derselben Förderverpflichtung erhöht
# die Stufe ab dem zweiten Verstoß um eine Stufe usw.; Kumulation durch Addition,
# höchstens 100 % der Jahresprämie.
effective_stage(f) := min_of(7, f.stage + max_of(0, object.get(f, "repeat_index", 1) - 1))

findings := object.get(application, "findings", [])

sanction_percent_total := min_of(
	stages.max_cumulative_percent,
	sum([stage_percent(effective_stage(f), year) | some f in findings]),
)

# O6_1C-SANC-002: Zweimal 100 %-Kürzung in der Förderperiode -> Ausschluss
# und Rückforderung der im Vertragszeitraum gewährten Prämie.
full_cuts_in_period := object.get(application, "full_cuts_in_period", 0) + count([f | some f in findings; effective_stage(f) == 7])

excluded_from_measure if full_cuts_in_period >= stages.exclusion_after_full_cuts_in_period

# O6_1C-SANC-004: Übererklärung (§§ 42, 46 GSP-AV).
area_basis(declared, determined) := determined - (params.general.overdeclaration_penalty_multiplier * (declared - determined)) if {
	declared > determined
	overdeclaration_material(declared, determined)
}

area_basis(declared, determined) := determined if {
	declared > determined
	not overdeclaration_material(declared, determined)
}

area_basis(declared, determined) := declared if declared <= determined

overdeclaration_material(declared, determined) if {
	declared - determined > params.general.overdeclaration_tolerance_share * determined
}

overdeclaration_material(declared, determined) if {
	declared - determined > params.general.overdeclaration_tolerance_ha
}

sanctioned_area_basis_ha(declared, determined) := max_of(0, area_basis(declared, determined))

# O6_1C-SANC-006: Verweigerung/Verhinderung der Vor-Ort-Kontrolle ohne höhere
# Gewalt -> Antrag abgelehnt, keine Prämie, Verträge beendet.
application_rejected_for_control_refusal if {
	application.on_site_control_refused == true
	not application.control_refusal_due_to_force_majeure == true
}

# O6_1C-FM-001: Höhere Gewalt binnen drei Wochen (21 Tage) ab Möglichkeit
# geltend zu machen.
ns_per_day := ((24 * 60) * 60) * 1000000000

days_between(d1, d2) := (time.parse_ns("2006-01-02", d2) - time.parse_ns("2006-01-02", d1)) / ns_per_day

force_majeure_claim_timely(claim) if {
	days_between(claim.able_to_notify_date, claim.notification_date) <= params.general.force_majeure_notification_days
}

force_majeure_case_listed(case_id) if {
	some row in data.o6_1c.force_majeure_cases.rows
	row.id == case_id
}

force_majeure_claims := object.get(application, "force_majeure_claims", [])

recognisable_force_majeure_claims contains c if {
	some c in force_majeure_claims
	force_majeure_claim_timely(c)
}

late_force_majeure_claims contains c if {
	some c in force_majeure_claims
	not force_majeure_claim_timely(c)
}

# O6_1C-SANC-007: Reihenfolge bei Mehrfachkürzungen (SRL 1.12.2).
reduction_order := [row.step | some row in data.o6_1c.multiple_reduction_order.rows]

